import hashlib,json,sys,time
from fractions import Fraction as F
from pathlib import Path
start=time.monotonic()
b=Path('docs/design/proposal/architecture')
paths=[b/'uncertainty-fixtures-v1.json',b/'uncertainty-chaining-fixtures-v1.json',Path('data/accounting-master/deliverables/P16/architecture.json')]
u,c,architecture=[json.loads(p.read_text()) for p in paths];r=c['records']
checks=[];calculations={}
def note(name,ok,detail):checks.append({'question':name,'passed':bool(ok),'evidence':detail})
def fracmap(x):return {k:F(v) for k,v in x.items()}
def show(x):return {k:str(v) for k,v in x.items()}
def normalize(p,f):
 w={s:p[s]*f[s] for s in p};z=sum(w.values());return z,{s:w[s]/z for s in p}
for name,bundle in c['bundles'].items():
 law=r[bundle['model_ref']];lineage=r[bundle['lineage_ref']];view=r[bundle['view_ref']];result=r[bundle['result_ref']]
 parent=fracmap(r[lineage['parent_model_ref']]['masses']);f=fracmap(lineage['factor_values']);z,q=normalize(parent,f)
 calculations[name]={'parent':show(parent),'factor':show(f),'normalizer':str(z),'posterior':show(q)}
 note(name+' exact law',z==F(lineage['normalizer']) and q==fracmap(law['masses'])==fracmap(view['masses'])==fracmap(result['payload']['posterior']),bundle)
 note(name+' unchanged selection',result['state_before']==result['state_after'],result['state_after'])
 note(name+' law/view identity',view['model_ref']==bundle['model_ref'] and law['view_ref']==bundle['view_ref'],[bundle['view_ref'],bundle['model_ref']])
p=fracmap(r['UC.law@1']['masses']);kernel=r['CH.kernel.DE@1'];d=fracmap(kernel['p_D_1']);e=fracmap(kernel['p_E_1_given_D_1']);e0=fracmap(kernel['p_E_1_given_D_0'])
for s in p:
 joint=[d[s]*e[s],d[s]*(1-e[s]),(1-d[s])*e0[s],(1-d[s])*(1-e0[s])]
 note('binary kernel '+s,sum(joint)==1 and min(joint)>=0,[str(x) for x in joint])
z,q=normalize(p,{s:d[s]*e[s] for s in p});calculations['direct_joint']={'normalizer':str(z),'posterior':show(q)}
note('conditional sequential equals direct joint',z==F(c['matched_alternative']['joint_normalizer']) and q==fracmap(r['CH.law.D_then_E@1']['masses']),calculations['direct_joint'])
completed=['a','b'];m=sum(p[s] for s in completed);contribution=p['a']*10+p['b']*20
uc={x['id']:x for x in u['cases']};out=uc['UC11']['expected']['payload'];cond=uc['UC12']['expected']['payload']
calculations['partial_outcome']={'completed_mass':str(m),'unresolved_mass':str(1-m),'completed_contribution':str(contribution),'conditional_completion_mean':str(contribution/m)}
note('partial contribution distinct from mean',m==F(out['completed_mass']) and 1-m==F(out['unresolved_mass']) and contribution==F(out['completed_unnormalized_contribution']) and contribution/m==F(cond['mean']) and out['unconditional_mean'] is None,calculations['partial_outcome'])
partition=out['partition'];members=[x for xs in partition.values() for x in xs];note('disjoint complete partition',len(members)==len(set(members)) and set(members)==set(p),partition)
for case in c['cases']:
 if case['kind']=='reject':
  x=r[case['expected_ref']];note(case['id']+' rejection preserves state',x['state_before']==x['state_after'] and x['domain_writes']==[] and x['proposed_view_ref'] is None,x['reason_codes'])
for admission in c['admissions']:
 receipt=r[admission['receipt_ref']];decision=r[admission['admission_ref']];attachment=r[admission['attachment_ref']]
 note('admission '+admission['id'],receipt['state_before']==receipt['state_after'] and decision['view_ref']==attachment['view_ref'] and decision['model_ref']==attachment['model_ref'] and bool(decision['authority']) and bool(decision['rationale']),admission)
# Follow typed references independently of the saved verification script.
def refs(x):
 found=set()
 if isinstance(x,dict):
  for k,v in x.items():
   if k.endswith('_ref') and isinstance(v,str):found.add(v)
   elif k.endswith('_refs') and isinstance(v,list):found.update(y for y in v if isinstance(y,str))
   if k!='dependencies':found.update(refs(v))
 elif isinstance(x,list):
  for v in x:found.update(refs(v))
 return found
missing={k:sorted(refs(v)-set(r)) for k,v in r.items() if refs(v)-set(r)}
note('all typed registry references resolve',not missing,missing)
dep_errors={}
for k,v in r.items():
 if 'dependencies' not in v:continue
 seen=set();todo=list(refs(v))
 while todo:
  ref=todo.pop()
  if ref in seen or ref not in r:continue
  seen.add(ref);todo.extend(refs(r[ref])-seen)
 absent=seen-set(v['dependencies'])-{k}
 if absent:dep_errors[k]=sorted(absent)
note('declared dependency closure',not dep_errors,dep_errors)
canonical=lambda x:hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':')).encode()).hexdigest()
import_errors=[k for k,h in c['imported_record_hashes'].items() if canonical(r[k])!=h or r[k]!=u['records'][k]]
note('original 60 imported records preserved',not import_errors,import_errors)
def hashrefs(x):
 if isinstance(x,dict):
  if isinstance(x.get('path'),str) and isinstance(x.get('sha256'),str):yield x
  for v in x.values():yield from hashrefs(v)
 elif isinstance(x,list):
  for v in x:yield from hashrefs(v)
audit=list(hashrefs(architecture));bad=[]
for x in audit:
 pth=Path(x['path'])
 if not pth.is_file() or hashlib.sha256(pth.read_bytes()).hexdigest()!=x['sha256']:bad.append(x['path'])
note('architecture reference hashes',not bad,{'references':len(audit),'mismatches':bad})
# Report earlier claims at their recorded hashes; do not rerun them.
prior={}
for f in ['uncertainty-verification-v1.json','uncertainty-chaining-verification-v1.json']:
 x=json.loads((b/f).read_text()); pins=x.get('input_hashes',{}); mismatches=[]
 if isinstance(pins,dict):
  for path,h in pins.items():
   pth=Path(path)
   if isinstance(h,str) and (not pth.is_file() or hashlib.sha256(pth.read_bytes()).hexdigest()!=h):mismatches.append(path)
 prior[f]={'recorded_input_count':len(pins),'current_mismatches':mismatches,'rerun':False}
manifest={'command':'python3 /tmp/p16-uncertainty-assessment.py','environment':sys.version,'packages':'Python standard library only','git_commit':'unavailable; repository .git marker is not usable; content hashes supplied','cpu_gpu':'CPU arithmetic; no GPU framework imported or device accessed','seeds':'N/A: deterministic rational arithmetic','data_version':'SHA-256-pinned authored fixtures','plan':'data/accounting-master/runs/20261004T202513-2bc09c08/P16/replan-2/plan-0.response.json','result':'docs/design/proposal/architecture/uncertainty-assessment-v1.md','wall_seconds':time.monotonic()-start}
report={'schema_version':'accdsl.proposal.uncertainty.assessment.calculations.v1','product_implemented':False,'human_acceptance':'pending','scope':'independent recomputation of authored specification examples; not runtime tests or formal acceptance','input_hashes':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths},'calculations':calculations,'checks':checks,'historical_reports':prior,'manifest':manifest,'diagnostic_source':Path(__file__).read_text()}
outpath=b/'uncertainty-assessment-calculations-v1.json'
assert not outpath.exists();outpath.write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'output':str(outpath),'checks':len(checks),'failures':[x for x in checks if not x['passed']],'historical_reports':prior},indent=2))
